package GUI;
import GUI.components.*; import Program.model.User; import Program.service.*; import Program.utils.SessionManager; import javafx.scene.*; import javafx.scene.effect.GaussianBlur; import javafx.scene.layout.*; import javafx.scene.paint.Color; import javafx.scene.shape.Circle; import javafx.stage.Stage;
public class MainUI {private final Stage stage; private final Scene scene; private final AuthService auth=new AuthService(); private final TransactionService transactions=new TransactionService(); private final BudgetService budgets=new BudgetService(); private BorderPane shell; private Sidebar sidebar;
 public MainUI(Stage stage){this.stage=stage;StackPane root=new StackPane();Circle blue=new Circle(260,Color.web("#38BDF8",.10));blue.setTranslateX(-500);blue.setTranslateY(-280);blue.setEffect(new GaussianBlur(70));Circle purple=new Circle(310,Color.web("#A78BFA",.09));purple.setTranslateX(520);purple.setTranslateY(310);purple.setEffect(new GaussianBlur(80));StackPane content=new StackPane();content.setId("content-layer");root.getChildren().addAll(blue,purple,content);scene=new Scene(root,1450,900);scene.getStylesheets().add(getClass().getResource("/styles/style.css").toExternalForm());stage.setScene(scene);stage.setTitle("Expense Intelligence — Smart Personal Finance Manager");stage.setMinWidth(1050);stage.setMinHeight(700);}
 private StackPane layer(){return (StackPane)((StackPane)scene.getRoot()).getChildren().get(2);} private void set(Node n){layer().getChildren().setAll(n);} public void showLogin(){set(new LoginUI(this,auth));stage.show();} public void showRegister(){set(new RegisterUI(this,auth));}
 public void showApp(User user){shell=new BorderPane();sidebar=new Sidebar(this::navigate);shell.setLeft(sidebar);shell.setTop(new Header(user));shell.getStyleClass().add("shell");set(shell);navigate("Dashboard");}
 public void navigate(String page){if("Logout".equals(page)){SessionManager.logout();showLogin();return;}User u=SessionManager.currentUser();if(u==null){showLogin();return;}if(sidebar!=null)sidebar.select(page);Node content=switch(page){case "Dashboard"->new DashboardUI(u,transactions,budgets,this);case "Expenses"->new ExpenseUI(u,this);case "Income"->new IncomeUI(u,this);case "Budgets"->new BudgetUI(u,this);case "Transactions"->new TransactionUI(u,this);case "Reports"->new ReportUI(u,this);case "AI Intelligence"->new AIIntelligenceUI(this);case "Spending Analysis"->new SpendingAnalysisUI(u,this);case "Financial Advisor"->new FinancialAdvisorUI(u,this);case "Budget Recommendation"->new BudgetRecommendationUI(u,this);case "Settings"->new SettingsUI(u,this,auth);default->new DashboardUI(u,transactions,budgets,this);};shell.setCenter(content);}
}
